PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar check ("role" in ('admin', 'responsable_entreprise', 'employe')) not null default 'employe', "entreprise_id" integer);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" varchar not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "entreprises" ("id" integer primary key autoincrement not null, "nom" varchar not null, "ninea" varchar not null, "adresse" text not null, "email" varchar not null, "telephone" varchar not null, "secteur_activite" varchar, "date_creation" date, "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "absences" ("id" integer primary key autoincrement not null, "type" varchar check ("type" in ('conge', 'maladie', 'permission', 'autre')) not null, "date_debut" date not null, "date_fin" date not null, "motif" text, "nombre_jours" integer not null, "statut" varchar check ("statut" in ('en_attente', 'approuvee', 'refusee')) not null default 'en_attente', "employe_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("employe_id") references "employes"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "bulletin_salaires" ("id" integer primary key autoincrement not null, "mois" integer not null, "annee" integer not null, "salaire_brut" numeric not null, "total_primes" numeric not null default '0', "total_retenues" numeric not null default '0', "salaire_net" numeric not null, "date_generation" datetime not null, "employe_id" integer not null, "entreprise_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("employe_id") references "employes"("id") on delete cascade, foreign key("entreprise_id") references "entreprises"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "element_salaires" ("id" integer primary key autoincrement not null, "type" varchar check ("type" in ('prime', 'indemnite', 'avantage')) not null, "nom" varchar not null, "montant" numeric not null, "recurrent" tinyint(1) not null default '0', "description" text, "employe_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("employe_id") references "employes"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "employes" ("id" integer primary key autoincrement not null, "nom" varchar not null, "prenom" varchar not null, "email" varchar not null, "telephone" varchar, "matricule" varchar not null, "date_entree" date not null, "salaire_base" numeric not null, "poste" varchar, "departement" varchar, "statut" varchar check ("statut" in ('actif', 'inactif', 'suspendu')) not null default 'actif', "entreprise_id" integer not null, "user_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("entreprise_id") references "entreprises"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "retenues" ("id" integer primary key autoincrement not null, "nom" varchar not null, "type" varchar check ("type" in ('cotisation_sociale', 'impot', 'avance', 'autre')) not null, "montant" numeric not null, "mois" integer not null, "annee" integer not null, "description" text, "employe_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("employe_id") references "employes"("id") on delete cascade);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE UNIQUE INDEX "entreprises_ninea_unique" on "entreprises" ("ninea");
CREATE UNIQUE INDEX "bulletin_salaires_employe_id_mois_annee_unique" on "bulletin_salaires" ("employe_id", "mois", "annee");
CREATE UNIQUE INDEX "employes_email_unique" on "employes" ("email");
CREATE UNIQUE INDEX "employes_matricule_unique" on "employes" ("matricule");
COMMIT;
